# 3. Dynamic Subtype Extractor
AVAILABLE_SUBTYPES = list(set([ex["subtype"] for ex in EXAMPLE_POOL]))
intensities = ["3/10", "4/10", "5/10", "6/10", "7/10", "8/10", "9/10", "10/10"]

DATASET_FILE = "nirbaan_synthetic_dataset.jsonl"

def build_few_shot_prompt(examples):
    prompt = ""
    for i, ex in enumerate(examples):
        prompt += f"=== EXAMPLE {i+1} ===\n"
        prompt += json.dumps({
            "obsession": ex["obsession"],
            "compulsion": ex["compulsion"],
            "feared_consequence": ex["feared_consequence"],
            "intensity": ex["intensity"],
            "script": ex["script"]
        }, indent=2) + "\n\n"
    return prompt

print("🚀 Starting the Nirbaan Data Factory: Generating Maximum Dread Scripts...")

# 4. The Generation Loop
for i in range(1, 1001):
    target_subtype = random.choice(AVAILABLE_SUBTYPES)
    target_intensity = random.choice(intensities)
    
    matching_examples = [ex for ex in EXAMPLE_POOL if ex.get("subtype") == target_subtype]
    num_to_take = min(3, len(matching_examples))
    dynamic_examples = random.sample(matching_examples, num_to_take)
        
    few_shot_text = build_few_shot_prompt(dynamic_examples)
    
    # --- UPGRADED: MAXIMUM TERROR SYSTEM PROMPT ---
    # --- UPGRADED: MAXIMUM TERROR + PERFECT MIMICRY ---
    system_prompt = """
You are a strict, clinical psychiatrist writing Exposure and Response Prevention (ERP) scripts for severe OCD.

CRITICAL INSTRUCTIONS FOR THE SCRIPT:
1. PERFECT MIMICRY: You must deeply analyze the provided examples and perfectly replicate their exact writing style, perspective, pacing, and clinical tone. Do not deviate from their structural format.
2. ZERO REASSURANCE: You must NEVER include phrases like "it's just OCD", "this is my exposure", "I am doing this to get better", or "these are just thoughts". The script must be a pure, unbroken, first-person narrative of the patient's absolute worst-case scenario happening in real-time.
3. STRICT INTENSITY SCALING: The level of psychological terror, graphic detail, and physiological dread MUST precisely match the requested `intensity` score. A 4/10 is highly distressing uncertainty. A 9/10 or 10/10 must be visceral, brutal, and completely horrifying, focusing on absolute ruin and maximum psychological terror.
4. NO EROTICA / NO SENSELESS GORE: Focus strictly on the psychological dread, guilt, loss of identity, and the devastating social/legal consequences of the obsession.
5. SCRIPT LENGTH: The script MUST be between 350 and 500 words long, broken into 3 to 4 substantial paragraphs.
6. STRICT JSON OUTPUT: Output ONLY a valid JSON object.
"""

    user_prompt = f"""
Here are exact examples of the "{target_subtype}" category. Notice their clinical, devastating tone and exact formatting:
{few_shot_text}

Generate a brand new, highly detailed ERP training script for the following category:
- OCD Subtype: {target_subtype}
- Script Intensity: {target_intensity}

INSTRUCTIONS:
Create an obsession, a compulsion, a feared consequence, and an imaginal exposure script.
- STRICTLY FOLLOW the writing style of the examples above.
- Make the script brutal, realistic, and completely devoid of reassurance. 
- Fully commit to the patient's worst fear.

Return ONLY a JSON object with exactly these keys:
"obsession" (string)
"compulsion" (string)
"feared_consequence" (string)
"intensity" (string, matching {target_intensity})
"script" (string, the 350-500 word nightmare narrative)
    """
    
    print(f"[{i}/1000] Generating: {target_subtype} (Intensity: {target_intensity})...")
    
    try:
        response = client.chat.completions.create(
            model="nousresearch/hermes-3-llama-3.1-70b", 
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt}
            ],
            response_format={"type": "json_object"},
            temperature=0.6 
        )
        
        raw_json_str = response.choices[0].message.content
        data = json.loads(raw_json_str)
        
        # String Scrubbing
        clean_script = data["script"].replace("\\n", " ").replace("\n\n", " ").replace("\n", " ").strip()
        
        # Perfect formatting assembly
        final_text = f"INPUT:\nObsession: {data['obsession'].strip()}\nCompulsion: {data['compulsion'].strip()}\nFeared consequence: {data['feared_consequence'].strip()}\nScript intensity: {data['intensity'].strip()}\nExposure type: imaginal\n\nOUTPUT:\n{clean_script}"
        
        final_jsonl_entry = {"text": final_text}
        
        with open(DATASET_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(final_jsonl_entry, ensure_ascii=False) + "\n")
                
        print(f"✅ Success! Saved script {i}/1000.")
        time.sleep(1.5)
            
    except Exception as e:
        print(f"❌ API Call Failed on script {i}: {e}")
        time.sleep(5)

print(f"\n🎉 DATASET COMPLETE! Check {DATASET_FILE}")